window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-165a4b67fc795411"]={"versions": [{"id": "FIG-165a4b67fc795411", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform Spezifikation (TPS Manifest Specification). Das Diagramm spezifiziert das Metamodell zur Modellierung von Prüfsummen einzelner Artefakte (<code>ArtifactChecksum</code>) eines Software-Clusters (<code>SoftwareCluster</code>) sowie deren Verknüpfung mit kryptografischen Treibern bzw. Anbietern (<code>CryptoProvider</code>) und zugehöriger Dokumentation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Entitäten sowie deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>SoftwareCluster</code> (spezialisiert <code>ARElement</code>): Besitzt die Attribute <code>typeApproval: String [0..1]</code>, <code>vendorId: PositiveInteger</code> und <code>version: StrongRevisionLabelString</code>. Enthält per Komposition mit Stereotyp <code>«atpSplitable»</code> über die Rolle <code>+artifactChecksum</code> mit Multiplizität <code>0..*</code> Artefakt-Prüfsummen. Referenziert <code>Documentation</code> über zwei gerichtete Assoziationen: <code>+license</code> (Multiplizität <code>0..*</code>) und <code>+releaseNotes</code> (Multiplizität <code>0..1</code>).\n</li><li><code>ArtifactChecksum</code> (spezialisiert <code>Identifiable</code>): Repräsentiert die Prüfsumme einer konkreten Datei oder eines Artefakts. Attribute sind <code>checksumValue: String [0..1]</code> und <code>«atpIdentityContributor» + uri: UriString [0..1]</code>.\n</li><li><code>ArtifactChecksumToCryptoProviderMapping</code> (spezialisiert <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code>): Dient als Zuordnungselement. Referenziert über die gerichtete Assoziation <code>+artifactChecksum</code> mit Multiplizität <code>0..*</code> Instanzen von <code>ArtifactChecksum</code> und über die gerichtete Assoziation <code>+cryptoProvider</code> mit Multiplizität <code>0..1</code> ein Ziel-Krypto-Element.\n</li><li><code>CryptoProvider</code> (spezialisiert <code>Identifiable</code>): Repräsentiert den Krypto-Dienstleister. Referenziert über die gerichtete Assoziation <code>+cryptoProviderDocumentation</code> mit Multiplizität <code>0..1</code> eine Instanz von <code>Documentation</code>.\n</li><li><code>Documentation</code> (spezialisiert <code>ARElement</code>): Repräsentiert Dokumentationsobjekte wie Lizenzinformationen, Release-Notes oder Krypto-Dokumentationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Instanziierung erfolgt deklarativ in AUTOSAR-Manifesten: Ein <code>SoftwareCluster</code> deklariert seine Prüfsummen über <code>ArtifactChecksum</code>. Zur Verifikation oder kryptografischen Absicherung stellt das Mapping <code>ArtifactChecksumToCryptoProviderMapping</code> die Relation zwischen den betroffenen Artefakt-Prüfsummen und dem ausführenden <code>CryptoProvider</code> her.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierer und Manifest-Generatoren müssen beachten:</p>\n<ul class=\"fig-list\"><li><code>SoftwareCluster.vendorId</code> und <code>SoftwareCluster.version</code> sind Pflichtattribute (Multiplizität 1).\n</li><li>Die Komposition von <code>ArtifactChecksum</code> ist mit <code>«atpSplitable»</code> versehen und kann somit auf mehrere ARXML-Dateien aufgeteilt werden.\n</li><li>Das Attribut <code>uri</code> in <code>ArtifactChecksum</code> trägt das Stereotyp <code>«atpIdentityContributor»</code>, wodurch der URI-Pfad zur eindeutigen Identifikation des Prüfsummen-Eintrags im AUTOSAR-Namensraum beiträgt.\n</li><li>Mappings ermöglichen eine lose Kopplung zwischen den Deployment-Artefakten und den kryptografischen Bereitstellern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5c6d3ecec96e601a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform Spezifikation (TPS Manifest Specification). Das Diagramm spezifiziert das Metamodell zur Modellierung von Prüfsummen einzelner Artefakte (<code>ArtifactChecksum</code>) eines Software-Clusters (<code>SoftwareCluster</code>) sowie deren Verknüpfung mit kryptografischen Treibern bzw. Anbietern (<code>CryptoProvider</code>) und zugehöriger Dokumentation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Entitäten sowie deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>SoftwareCluster</code> (spezialisiert <code>ARElement</code>): Besitzt die Attribute <code>installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code>, <code>typeApproval: String [0..1]</code>, <code>vendorId: PositiveInteger [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>. Enthält per Komposition mit Stereotyp <code>«atpSplitable»</code> über die Rolle <code>+artifactChecksum</code> mit Multiplizität <code>0..*</code> Artefakt-Prüfsummen. Referenziert <code>Documentation</code> über zwei gerichtete Assoziationen: <code>+license</code> (Multiplizität <code>0..*</code>) und <code>+releaseNotes</code> (Multiplizität <code>0..1</code>).\n</li><li><code>ArtifactChecksum</code> (spezialisiert <code>Identifiable</code>): Repräsentiert die Prüfsumme einer konkreten Datei oder eines Artefakts. Attribute sind <code>checksumValue: String [0..1]</code> und <code>«atpIdentityContributor» + uri: UriString [0..1]</code>.\n</li><li><code>ArtifactChecksumToCryptoProviderMapping</code> (spezialisiert <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code>): Dient als Zuordnungselement. Referenziert über die gerichtete Assoziation <code>+artifactChecksum</code> mit Multiplizität <code>0..*</code> Instanzen von <code>ArtifactChecksum</code> und über die gerichtete Assoziation <code>+cryptoProvider</code> mit Multiplizität <code>0..1</code> ein Ziel-Krypto-Element.\n</li><li><code>CryptoProvider</code> (spezialisiert <code>Identifiable</code>): Repräsentiert den Krypto-Dienstleister. Referenziert über die gerichtete Assoziation <code>+cryptoProviderDocumentation</code> mit Multiplizität <code>0..1</code> eine Instanz von <code>Documentation</code>.\n</li><li><code>Documentation</code> (spezialisiert <code>ARElement</code>): Repräsentiert Dokumentationsobjekte wie Lizenzinformationen, Release-Notes oder Krypto-Dokumentationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Instanziierung erfolgt deklarativ in AUTOSAR-Manifesten: Ein <code>SoftwareCluster</code> deklariert seine Prüfsummen über <code>ArtifactChecksum</code>. Zur Verifikation oder kryptografischen Absicherung stellt das Mapping <code>ArtifactChecksumToCryptoProviderMapping</code> die Relation zwischen den betroffenen Artefakt-Prüfsummen und dem ausführenden <code>CryptoProvider</code> her.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierer und Manifest-Generatoren müssen beachten:</p>\n<ul class=\"fig-list\"><li><code>SoftwareCluster.vendorId</code> und <code>SoftwareCluster.version</code> sind optional (<code>[0..1]</code>).\n</li><li>Das Installationsverhalten kann optional über <code>SoftwareCluster.installationBehavior</code> gesteuert werden.\n</li><li>Die Komposition von <code>ArtifactChecksum</code> ist mit <code>«atpSplitable»</code> versehen und kann auf mehrere ARXML-Dateien aufgeteilt werden.\n</li><li>Das Attribut <code>uri</code> in <code>ArtifactChecksum</code> trägt das Stereotyp <code>«atpIdentityContributor»</code>, wodurch der URI-Pfad zur eindeutigen Identifikation des Prüfsummen-Eintrags im Namensraum beiträgt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d7cd9693637fd267", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform Spezifikation (TPS Manifest Specification). Das Diagramm spezifiziert das Metamodell zur Modellierung von Prüfsummen einzelner Artefakte (<code>ArtifactChecksum</code>) eines Software-Clusters (<code>SoftwareCluster</code>) sowie deren Verknüpfung mit kryptografischen Treibern bzw. Anbietern (<code>CryptoProvider</code>) und zugehöriger Dokumentation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Entitäten sowie deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>SoftwareCluster</code> (spezialisiert <code>UploadableDeploymentElement</code>): Besitzt die Attribute <code>installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code>, <code>typeApproval: String [0..1]</code>, <code>vendorId: PositiveInteger [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>. Enthält per Komposition mit Stereotyp <code>«atpSplitable»</code> über die Rolle <code>+artifactChecksum</code> mit Multiplizität <code>0..*</code> Artefakt-Prüfsummen. Referenziert <code>Documentation</code> über zwei gerichtete Assoziationen: <code>+license</code> (Multiplizität <code>0..*</code>) und <code>+releaseNotes</code> (Multiplizität <code>0..1</code>).\n</li><li><code>ArtifactChecksum</code> (spezialisiert <code>Identifiable</code>): Repräsentiert die Prüfsumme einer konkreten Datei oder eines Artefakts. Attribute sind <code>checksumValue: String [0..1]</code> und <code>«atpIdentityContributor» + uri: UriString [0..1]</code>.\n</li><li><code>ArtifactChecksumToCryptoProviderMapping</code> (spezialisiert <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code>): Dient als Zuordnungselement. Referenziert über die gerichtete Assoziation <code>+artifactChecksum</code> mit Multiplizität <code>0..*</code> Instanzen von <code>ArtifactChecksum</code> und über die gerichtete Assoziation <code>+cryptoProvider</code> mit Multiplizität <code>0..1</code> ein Ziel-Krypto-Element.\n</li><li><code>CryptoProvider</code> (spezialisiert <code>Identifiable</code>): Repräsentiert den Krypto-Dienstleister. Referenziert über die gerichtete Assoziation <code>+cryptoProviderDocumentation</code> mit Multiplizität <code>0..1</code> eine Instanz von <code>Documentation</code>.\n</li><li><code>Documentation</code> (spezialisiert <code>ARElement</code> und <code>UploadableDesignElement</code>): Repräsentiert Dokumentationsobjekte wie Lizenzinformationen, Release-Notes oder Krypto-Dokumentationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Instanziierung erfolgt deklarativ in AUTOSAR-Manifesten: Ein <code>SoftwareCluster</code> deklariert seine Prüfsummen über <code>ArtifactChecksum</code>. Zur Verifikation oder kryptografischen Absicherung stellt das Mapping <code>ArtifactChecksumToCryptoProviderMapping</code> die Relation zwischen den betroffenen Artefakt-Prüfsummen und dem ausführenden <code>CryptoProvider</code> her.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierer und Manifest-Generatoren müssen beachten:</p>\n<ul class=\"fig-list\"><li><code>SoftwareCluster</code> wird als <code>UploadableDeploymentElement</code> klassifiziert.\n</li><li><code>Documentation</code> wird sowohl als <code>ARElement</code> als auch als <code>UploadableDesignElement</code> typisiert.\n</li><li><code>SoftwareCluster.vendorId</code> und <code>SoftwareCluster.version</code> sind optional (<code>[0..1]</code>).\n</li><li>Die Komposition von <code>ArtifactChecksum</code> ist mit <code>«atpSplitable»</code> versehen.\n</li><li>Das Attribut <code>uri</code> in <code>ArtifactChecksum</code> trägt das Stereotyp <code>«atpIdentityContributor»</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1e4c3fae3e6dc587", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform Spezifikation (TPS Manifest Specification). Das Diagramm spezifiziert das Metamodell zur Modellierung von Prüfsummen einzelner Artefakte (<code>ArtifactChecksum</code>) eines Software-Clusters (<code>SoftwareCluster</code>) sowie deren Verknüpfung mit kryptografischen Treibern bzw. Anbietern (<code>CryptoProvider</code>) und zugehöriger Dokumentation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Entitäten sowie deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>SoftwareCluster</code> (spezialisiert <code>UploadableDeploymentElement</code>): Besitzt die Attribute <code>installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code>, <code>typeApproval: String [0..1]</code>, <code>vendorId: PositiveInteger [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>. Enthält per Komposition mit Stereotyp <code>«atpSplitable»</code> über die Rolle <code>+artifactChecksum</code> mit Multiplizität <code>0..*</code> Artefakt-Prüfsummen. Referenziert <code>Documentation</code> über zwei gerichtete Assoziationen: <code>+license</code> (Multiplizität <code>0..*</code>) und <code>+releaseNotes</code> (Multiplizität <code>0..1</code>).\n</li><li><code>ArtifactChecksum</code> (spezialisiert <code>Identifiable</code>): Repräsentiert die Prüfsumme einer konkreten Datei oder eines Artefakts. Attribute sind <code>checksumValue: String [0..1]</code> und <code>«atpIdentityContributor» + uri: UriString [0..1]</code>.\n</li><li><code>ArtifactChecksumToCryptoProviderMapping</code> (spezialisiert <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code>): Dient als Zuordnungselement. Referenziert über die gerichtete Assoziation <code>+artifactChecksum</code> mit Multiplizität <code>0..*</code> Instanzen von <code>ArtifactChecksum</code> und über die gerichtete Assoziation <code>+cryptoProvider</code> mit Multiplizität <code>0..1</code> ein Ziel-Krypto-Element.\n</li><li><code>CryptoProvider</code> (spezialisiert <code>Identifiable</code>): Repräsentiert den Krypto-Dienstleister. Referenziert über die gerichtete Assoziation <code>+cryptoProviderDocumentation</code> mit Multiplizität <code>0..1</code> eine Instanz von <code>Documentation</code>.\n</li><li><code>Documentation</code> (spezialisiert <code>ARElement</code> und <code>UploadableDesignElement</code>): Repräsentiert Dokumentationsobjekte wie Lizenzinformationen, Release-Notes oder Krypto-Dokumentationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Instanziierung erfolgt deklarativ in AUTOSAR-Manifesten: Ein <code>SoftwareCluster</code> deklariert seine Prüfsummen über <code>ArtifactChecksum</code>. Zur Verifikation oder kryptografischen Absicherung stellt das Mapping <code>ArtifactChecksumToCryptoProviderMapping</code> die Relation zwischen den betroffenen Artefakt-Prüfsummen und dem ausführenden <code>CryptoProvider</code> her.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierer und Manifest-Generatoren müssen beachten:</p>\n<ul class=\"fig-list\"><li><code>SoftwareCluster</code> wird als <code>UploadableDeploymentElement</code> klassifiziert.\n</li><li><code>Documentation</code> wird sowohl als <code>ARElement</code> als auch als <code>UploadableDesignElement</code> typisiert.\n</li><li><code>SoftwareCluster.vendorId</code> und <code>SoftwareCluster.version</code> sind optional (<code>[0..1]</code>).\n</li><li>Die Komposition von <code>ArtifactChecksum</code> ist mit <code>«atpSplitable»</code> versehen.\n</li><li>Das Attribut <code>uri</code> in <code>ArtifactChecksum</code> trägt das Stereotyp <code>«atpIdentityContributor»</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e1cface211ae332b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform Spezifikation (TPS Manifest Specification). Das Diagramm spezifiziert das Metamodell zur Modellierung von Prüfsummen einzelner Artefakte (<code>ArtifactChecksum</code>) eines Software-Clusters (<code>SoftwareCluster</code>) sowie deren Verknüpfung mit kryptografischen Treibern bzw. Anbietern (<code>CryptoProvider</code>) und zugehöriger Dokumentation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Entitäten sowie deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>SoftwareCluster</code> (spezialisiert <code>UploadableDeploymentElement</code>): Besitzt die Attribute <code>typeApproval: String [0..1]</code>, <code>vendorId: PositiveInteger [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>. Enthält per Komposition mit Stereotyp <code>«atpSplitable»</code> über die Rolle <code>+artifactChecksum</code> mit Multiplizität <code>0..*</code> Artefakt-Prüfsummen. Referenziert <code>Documentation</code> über zwei gerichtete Assoziationen: <code>+license</code> (Multiplizität <code>0..*</code>) und <code>+releaseNotes</code> (Multiplizität <code>0..1</code>).\n</li><li><code>ArtifactChecksum</code> (spezialisiert <code>Identifiable</code>): Repräsentiert die Prüfsumme einer konkreten Datei oder eines Artefakts. Attribute sind <code>checksumValue: String [0..1]</code> und <code>uri: UriString [0..1]</code>.\n</li><li><code>ArtifactChecksumToCryptoProviderMapping</code> (spezialisiert <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code>): Dient als Zuordnungselement. Referenziert über die gerichtete Assoziation <code>+artifactChecksum</code> mit Multiplizität <code>0..*</code> Instanzen von <code>ArtifactChecksum</code> und über die gerichtete Assoziation <code>+cryptoProvider</code> mit Multiplizität <code>0..1</code> ein Ziel-Krypto-Element.\n</li><li><code>CryptoProvider</code> (spezialisiert <code>Identifiable</code>): Repräsentiert den Krypto-Dienstleister. Referenziert über die gerichtete Assoziation <code>+cryptoProviderDocumentation</code> mit Multiplizität <code>0..1</code> eine Instanz von <code>Documentation</code>.\n</li><li><code>Documentation</code> (spezialisiert <code>ARElement</code> und <code>UploadableDesignElement</code>): Repräsentiert Dokumentationsobjekte wie Lizenzinformationen, Release-Notes oder Krypto-Dokumentationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Instanziierung erfolgt deklarativ in AUTOSAR-Manifesten: Ein <code>SoftwareCluster</code> deklariert seine Prüfsummen über <code>ArtifactChecksum</code>. Zur Verifikation oder kryptografischen Absicherung stellt das Mapping <code>ArtifactChecksumToCryptoProviderMapping</code> die Relation zwischen den betroffenen Artefakt-Prüfsummen und dem ausführenden <code>CryptoProvider</code> her.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierer und Manifest-Generatoren müssen beachten:</p>\n<ul class=\"fig-list\"><li><code>SoftwareCluster</code> besitzt kein Attribut <code>installationBehavior</code> mehr.\n</li><li>Das Attribut <code>uri</code> in <code>ArtifactChecksum</code> fungiert nicht mehr als <code>«atpIdentityContributor»</code>.\n</li><li>Die Komposition <code>artifactChecksum</code> bleibt als <code>«atpSplitable»</code> aufteilbar.\n</li><li>Attribute <code>vendorId</code> und <code>version</code> verbleiben optional mit Kardinalität <code>[0..1]</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-165a4b67fc795411", "to": "FIG-5c6d3ecec96e601a", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>SoftwareCluster: Attribut <code>installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code> hinzugefügt.\n</li><li>SoftwareCluster: Multiplizität von <code>vendorId</code> von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.\n</li><li>SoftwareCluster: Multiplizität von <code>version</code> von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.\n</li></ul>"}, {"from": "FIG-5c6d3ecec96e601a", "to": "FIG-d7cd9693637fd267", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>SoftwareCluster: Basisklasse von <code>ARElement</code> auf <code>UploadableDeploymentElement</code> geändert.\n</li><li>Documentation: Zusätzliche Vererbung/Spezialisierung <code>UploadableDesignElement</code> neben <code>ARElement</code> ergänzt.\n</li></ul>"}, {"from": "FIG-d7cd9693637fd267", "to": "FIG-1e4c3fae3e6dc587", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>SoftwareCluster / Documentation: Vertikale Anordnung der Rollen-Labels <code>+license</code> und <code>+releaseNotes</code> an den Assoziationspfeilen vertauscht/neu arrangiert.\n</li></ul>"}, {"from": "FIG-1e4c3fae3e6dc587", "to": "FIG-e1cface211ae332b", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>SoftwareCluster: Attribut <code>installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code> entfernt.\n</li><li>ArtifactChecksum: Stereotyp <code>«atpIdentityContributor»</code> am Attribut <code>uri</code> entfernt.\n</li><li>SoftwareCluster / Documentation: Reihenfolge der Rollen-Labels <code>+license</code> und <code>+releaseNotes</code> redaktionell zurückpositioniert.\n</li></ul>"}]};
